// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.impl;

import static org.assertj.core.api.Assertions.assertThat;

import org.eclipse.rdf4j.query.algebra.TupleFunctionCall;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

/**
 * {@link TupleFunctionEvaluationStatistics} (used by LuceneSail) overrides {@code meetNode} to estimate tuple function
 * calls; the base {@link EvaluationStatistics} must not intercept those calls before the subclass sees them.
 */
class TupleFunctionEvaluationStatisticsTest {

	private static TupleFunctionCall callWithUnboundArgument() {
		TupleFunctionCall call = new TupleFunctionCall();
		call.setURI("urn:f");
		call.addArgs(new Var("query"));
		call.addResultVars(new Var("result"));
		return call;
	}

	@Test
	void subclassEstimateIsNotShadowedByTheBaseCalculator() {
		TupleFunctionCall call = callWithUnboundArgument();
		// 10 per result var, regardless of unbound arguments: the subclass' own estimate
		assertThat(new TupleFunctionEvaluationStatistics().getCardinality(call)).isEqualTo(10.0);
	}

	@Test
	void baseCalculatorStillEstimatesTupleFunctionCalls() {
		TupleFunctionCall call = callWithUnboundArgument();
		assertThat(new EvaluationStatistics().getCardinality(call))
				.isGreaterThanOrEqualTo(new TupleFunctionEvaluationStatistics().getCardinality(call));
	}
}
